from __future__ import annotations

import json
from typing import IO

from secretscan.model import Finding, RunMeta


def render_json(w: IO[str], findings: list[Finding], meta: RunMeta) -> None:
    doc = {
        "meta": meta.to_dict(),
        "findings": [f.to_dict() for f in findings],
    }
    json.dump(doc, w, indent=2)
    w.write("\n")
